"use client";

import {
  Highlight,
  HighlightItem,
} from "@/components/sora-ui/effects/highlight";

const MENU_ITEMS = [
  { value: "inbox", label: "Inbox", count: 12 },
  { value: "drafts", label: "Drafts", count: 3 },
  { value: "sent", label: "Sent" },
  { value: "starred", label: "Starred" },
  { value: "archive", label: "Archive" },
];

export function HighlightClickDemo() {
  return (
    <div className="flex min-h-40 items-center justify-center">
      <Highlight
        className="rounded-md bg-foreground/8"
        defaultValue="inbox"
        mode="children"
        trigger="click"
      >
        {MENU_ITEMS.map(({ value, label, count }) => (
          <HighlightItem key={value} value={value}>
            <button
              className="flex w-48 cursor-pointer items-center justify-between px-3 py-2 text-sm"
              type="button"
            >
              <span>{label}</span>
              {count !== undefined && (
                <span className="text-xs text-foreground/40">{count}</span>
              )}
            </button>
          </HighlightItem>
        ))}
      </Highlight>
    </div>
  );
}
